import fs from "node:fs";
import { validateFinalNtQuiz } from "./validate-nt-quiz.mjs";
import { parseQuizReferences } from "./quiz-reference-ranges.mjs";
import path from "node:path";
import { LIFE_TOPICS, GUIDED_PLANS, BEGINNER_GUIDES } from "../src/content.js";
import { normBook, validRef } from "../src/domain.js";
export function auditContent(root = process.cwd()) {
  const approvedMaster = fs.existsSync(path.join(root, "reports/nt-quiz-final/manifest.json")) ? validateFinalNtQuiz(root) : null;
  const read = (f) => JSON.parse(fs.readFileSync(path.join(root, f), "utf8"));
  const books = read("data/index.json"),
    stories = read("data/stories.json"),
    index = {},
    counts = {};
  const aliases = {
    Apg: "ACT",
    Mt: "MAT",
    Mk: "MRK",
    Lk: "LUK",
    Joh: "JHN",
    Röm: "ROM",
    "1 Kor": "1CO",
    "2 Kor": "2CO",
    Gal: "GAL",
    Eph: "EPH",
    Phil: "PHP",
    Kol: "COL",
    "1 Thess": "1TH",
    "2 Thess": "2TH",
    "1 Tim": "1TI",
    "2 Tim": "2TI",
    Tit: "TIT",
    Phlm: "PHM",
    Hebr: "HEB",
    Jak: "JAS",
    "1 Petr": "1PE",
    "2 Petr": "2PE",
    "1 Joh": "1JN",
    "2 Joh": "2JN",
    "3 Joh": "3JN",
    Jud: "JUD",
    Offb: "REV",
  };
  for (const b of books) aliases[b.name] = b.code;
  const errors = [],
    warnings = [],
    parse = (text) => parseQuizReferences(text, books, aliases);
  for (const tr of ["otb", "l1912"]) {
    index[tr] = {};
    let chapters = 0,
      verses = 0;
    for (const b of books) {
      const data = read(`data/bibles/${tr}/${b.code}.json`);
      if (data.chapters.length !== b.chapters)
        errors.push(`${tr}/${b.code}: Kapitelanzahl`);
      index[tr][b.code] = data.chapters.map((c) => c.map((v) => Number(v[0])));
      chapters += data.chapters.length;
      verses += data.chapters.reduce((n, c) => n + c.length, 0);
    }
    counts[tr] = { books: books.length, chapters, verses };
  }
  const verify = (r, label) => {
    for (const tr of ["otb", "l1912"])
      try {
        validRef({ ...r, translation: tr }, index);
      } catch (err) {
        errors.push(`${label} (${tr}): ${err.message}`);
      }
  };
  const references = [
    ...LIFE_TOPICS.flatMap((t) => t.refs),
    ...GUIDED_PLANS.flatMap((p) =>
      p.days.map((d) => ({ book: d[1], chapter: d[2], from: d[3], to: d[4] })),
    ),
    ...BEGINNER_GUIDES.flatMap((p) =>
      p.days.map((d) => ({ book: d[1], chapter: d[2], from: d[3], to: d[4] })),
    ),
  ];
  references.forEach((r) => verify(r, JSON.stringify(r)));
  const ids = new Set();
  let questions = 0,
    verified = 0,
    pending = 0,
    approved = 0,
    missing = 0;
  for (const x of stories) {
    if (ids.has(x.id)) errors.push("Doppelte Story " + x.id);
    ids.add(x.id);
    verify(
      { book: x.book, chapter: x.chapter + 1, from: x.from, to: x.to },
      "Einheit " + x.id,
    );
    if (x.to === 999) warnings.push("Altes Ganzkapitel-Sentinel: " + x.id);
    if (!x.reflection?.trim()) errors.push("Reflexion fehlt: " + x.id);
    for (const [i, q] of x.questions.entries()) {
      questions++;
      if (
        q.a?.length !== 4 ||
        new Set(q.a).size !== 4 ||
        !Number.isInteger(q.c) ||
        q.c < 0 ||
        q.c > 3 ||
        !q.x?.trim()
      )
        errors.push("Fragenstruktur " + x.id + "/" + i);
      try {
        for (const ref of parse(q.ref || q.p)) verify(ref, "Frage " + x.id + "/" + i);
      } catch (err) {
        errors.push(err.message);
      }
    }
    if (x.verification?.status === "verse-checked")
      verified += x.questions.length;
    else if (x.kind === "chapter-quiz") {
      if (approvedMaster) approved += x.questions.length;
      else pending += x.questions.length;
    }
    else missing += x.questions.length;
  }
  const report = {
    bibles: counts,
    stories: stories.length,
    questions,
    books: new Set(stories.map((x) => x.book)).size,
    reflections: stories.length,
    uniqueReflections: new Set(stories.map((x) => x.reflection)).size,
    existingVerification: verified,
    editorialPending: pending,
    approvedNtMaster: approved,
    missingVerification: missing,
    situationPlanReferences: references.length,
    errors,
    warnings,
  };
  return { index, report };
}
if (process.argv[1] === new URL(import.meta.url).pathname) {
  const { index, report } = auditContent();
  console.log(JSON.stringify(report, null, 2));
  if (report.errors.length) process.exitCode = 1;
  else {
    fs.writeFileSync("data/reference-index.json", JSON.stringify(index));
    fs.writeFileSync(
      "data/content-report.json",
      JSON.stringify(report, null, 2),
    );
  }
}

import {validateImportedFields,validateImportedRelations} from './import-validation.js';
// The original keys remain readable. Migration never discards unknown fields.
export const KEYS = Object.freeze({
  main: "faithpath.v1.rebuild",
  plans: "faithpath.guidedPlans.v1",
  onboard: "faithpath.onboarding.v4",
  legacyOnboard: "faithpath.onboarding.v3",
  migration: "faithpath.backup.pre-v5",
  restore: "faithpath.backup.before-import",
  draft: "faithpath.draft.v4",
});
export const id = () =>
  globalThis.crypto?.randomUUID?.() ||
  `fp-${Date.now()}-${Math.random().toString(36).slice(2)}`;
export const now = () => new Date().toISOString();
const object = (x) => !!x && typeof x === "object" && !Array.isArray(x);
const clone = (x) => JSON.parse(JSON.stringify(x));
export const empty = () => ({
  version: 5,
  translation: "otb",
  paths: [],
  journal: [],
  highlights: [],
  reflections: [],
  quiz: {},
  events: [],
  reading: null,
  reminderSnoozes: {},
  dismissedGaps: {},
  reviews: [],
  guidedPlans: {},
  settings: {},
});
const arrays = [
  "paths",
  "journal",
  "highlights",
  "reflections",
  "events",
  "reviews",
];
export function validateShape(raw, strict = false) {
  if (!object(raw)) throw new Error("Das ist kein FaithPath-Datenstand.");
  if (raw.version > 5)
    throw new Error("Dieses Backup benötigt eine neuere FaithPath-Version.");
  for (const k of arrays) {
    if (raw[k] != null && !Array.isArray(raw[k]))
      throw new Error(`Ungültiger Bereich: ${k}.`);
    if ((raw[k] || []).some((x) => !object(x)))
      throw new Error(`Beschädigter Eintrag in ${k}.`);
  }
  if (
    strict &&
    !["paths", "journal", "highlights"].every((k) => Array.isArray(raw[k]))
  )
    throw new Error("Die erforderlichen FaithPath-Bereiche fehlen.");
  for (const p of raw.paths || []) {
    if (typeof p.title !== "string" || !p.title.trim())
      throw new Error("Ein Weg hat keinen gültigen Titel.");
    for (const k of ["steps", "milestones", "reviews", "links"])
      if (
        p[k] != null &&
        (!Array.isArray(p[k]) || p[k].some((x) => !object(x)))
      )
        throw new Error(`Ungültige ${k} im Weg.`);
    for (const k of ["steps", "milestones", "reviews"])
      for (const x of p[k] || [])
        if (typeof x.text !== "string")
          throw new Error("Ein Weg enthält beschädigten Text.");
  }
  for (const k of ["journal", "reflections"])
    for (const x of raw[k] || [])
      if (typeof x.text !== "string")
        throw new Error("Ein Eintrag enthält beschädigten Text.");
  for (const k of [
    "quiz",
    "reminderSnoozes",
    "dismissedGaps",
    "guidedPlans",
    "settings",
  ])
    if (raw[k] != null && !object(raw[k]))
      throw new Error(`Ungültiger Bereich: ${k}.`);
  for (const [plan, days] of Object.entries(raw.guidedPlans || {}))
    if (
      !object(days) ||
      Object.values(days).some((v) => typeof v !== "boolean")
    )
      throw new Error("Ungültiger Planfortschritt.");
  // Reject prototype-bearing input. All user strings are escaped by the view layer.
  const scan = (x) => {
    if (!x || typeof x !== "object") return;
    for (const k of Object.keys(x)) {
      if (["__proto__", "constructor", "prototype"].includes(k))
        throw new Error("Unsichere Importdatei.");
      scan(x[k]);
    }
  };
  scan(raw);
  for (const k of arrays) {
    const used = new Set();
    for (const x of raw[k] || []) {
      if (x.id != null && used.has(String(x.id)))
        throw new Error(`Doppelte ID in ${k}.`);
      if (x.id != null) used.add(String(x.id));
    }
  }
  return raw;
}
export function migrate(raw, legacyPlans = {}) {
  validateShape(raw);
  if (!object(legacyPlans))
    throw new Error("Der gespeicherte Planfortschritt ist beschädigt.");
  const s = { ...empty(), ...clone(raw), version: 5 };
  for (const k of ["quiz", "reminderSnoozes", "dismissedGaps", "settings"])
    s[k] ??= {};
  for (const k of arrays)
    s[k] = (s[k] || []).map((x) => ({ ...x, id: String(x.id || id()) }));
  s.guidedPlans = object(raw.guidedPlans)
    ? clone(raw.guidedPlans)
    : clone(legacyPlans);
  s.paths = s.paths.map((p) => ({
    ...p,
    steps: (p.steps || []).map((x) => ({ ...x, id: String(x.id || id()) })),
    milestones: (p.milestones || []).map((x) => ({
      ...x,
      id: String(x.id || id()),
    })),
    reviews: (p.reviews || []).map((x) => ({ ...x, id: String(x.id || id()) })),
    links: (p.links || []).map((x) => ({ ...x, id: String(x.id || id()) })),
  }));
  // Link only exact legacy mirrors, never infer a connection from similar prose.
  for (const j of s.journal) {
    if (j.reflectionId) continue;
    const rs = s.reflections.filter(
      (r) =>
        r.text === j.text &&
        r.date === j.date &&
        ((!r.ref && !j.ref) || JSON.stringify(r.ref) === JSON.stringify(j.ref)),
    );
    if (rs.length === 1) j.reflectionId = rs[0].id;
  }
  for (const p of s.paths)
    for (const l of p.links) {
      if (!l.reflectionId) continue;
      const r = s.reflections.find((x) => x.id === l.reflectionId);
      if (r) {
        r.pathIds = [...new Set([...(r.pathIds || []), p.id])];
        const j = s.journal.find((x) => x.reflectionId === r.id);
        if (j) j.pathIds = [...new Set([...(j.pathIds || []), p.id])];
      }
    }
  validateShape(s);
  return s;
}
export function createStore(storage) {
  let state = empty(),
    error = null,
    last = null;
  try {
    last = storage.getItem(KEYS.main);
    const raw = last ? JSON.parse(last) : {};
    const plansRaw = storage.getItem(KEYS.plans),
      plans = raw.guidedPlans ? {} : plansRaw ? JSON.parse(plansRaw) : {};
    state = migrate(raw, plans);
    if (last && raw.version !== 5) {
      if (!storage.getItem(KEYS.migration))
        storage.setItem(
          KEYS.migration,
          JSON.stringify({ raw: last, guidedPlansRaw: plansRaw, saved: now() }),
        );
      const serialized = JSON.stringify(state);
      storage.setItem(KEYS.main, serialized);
      last = serialized;
    }
  } catch (e) {
    error = e;
  }
  return {
    get state() {
      return state;
    },
    get error() {
      return error;
    },
    transact(change) {
      if (error)
        throw new Error(
          "Deine Daten konnten nicht sicher geladen werden. Bitte sichere zuerst den Originalstand.",
        );
      if (storage.getItem(KEYS.main) !== last)
        throw new Error(
          "Deine Daten wurden in einem anderen Tab geändert. Bitte lade FaithPath neu.",
        );
      const next = clone(state);
      change(next);
      validateShape(next);
      const serialized = JSON.stringify(next);
      try {
        storage.setItem(KEYS.main, serialized);
      } catch {
        throw new Error(
          "Nicht gespeichert: Der Gerätespeicher ist nicht verfügbar oder voll. Bitte exportiere ein Backup.",
        );
      }
      state = next;
      last = serialized;
      return state;
    },
    backup() {
      if(error)throw new Error("Deine Daten konnten nicht sicher geladen werden. Bitte sichere den Originalstand.");
      if(storage.getItem(KEYS.main)!==last)throw new Error("Deine Daten wurden in einem anderen Tab geändert. Bitte lade FaithPath vor dem Export neu.");
      return {
        app: "FaithPath",
        version: 4,
        schemaVersion: 5,
        exported: now(),
        data: clone(state),
        guidedPlans: clone(state.guidedPlans),
      };
    },
    prepareImport(input) {
      if (!object(input) || (input.app && input.app !== "FaithPath"))
        throw new Error("Kein FaithPath-Backup.");
      const raw = input.data || input;
      validateShape(raw, true);
      validateImportedFields(raw);
      const next=migrate(raw, input.guidedPlans || {});
      validateImportedRelations(next);
      return next;
    },
    restore(next) {
      validateShape(next, true);
      validateImportedFields(next);
      validateImportedRelations(next);
      if (storage.getItem(KEYS.main) !== last)
        throw new Error("Daten wurden inzwischen geändert. Bitte neu laden.");
      const previousRestore=storage.getItem(KEYS.restore);
      const safetyCopy=JSON.stringify({raw:last,guidedPlansRaw:storage.getItem(KEYS.plans),saved:now()});
      storage.setItem(KEYS.restore,safetyCopy);
      const serialized = JSON.stringify(next);
      try{storage.setItem(KEYS.main,serialized);}catch{
        // Main writes are atomic; preserve the older recovery copy when possible.
        try{if(storage.getItem(KEYS.restore)===safetyCopy){if(previousRestore!==null)storage.setItem(KEYS.restore,previousRestore);else storage.removeItem?.(KEYS.restore);}}catch{}
        throw new Error("Nicht wiederhergestellt: Der Gerätespeicher ist nicht verfügbar oder voll. Dein aktueller Stand bleibt erhalten.");
      }
      state = clone(next);
      last = serialized;
      error = null;
    },
    rawBackup() {
      return {
        app: "FaithPath-Recovery",
        main: storage.getItem(KEYS.main),
        guidedPlans: storage.getItem(KEYS.plans),
        migration: storage.getItem(KEYS.migration),
        beforeImport: storage.getItem(KEYS.restore),
      };
    },
  };
}

import test from 'node:test';import assert from 'node:assert/strict';import {empty,createStore,KEYS} from '../src/store.js';
const m=await import('../src/bible-notes.js').catch(()=>({}));const call=(name,...args)=>{assert.equal(typeof m[name],'function',name);return m[name](...args);};const ref={book:'JHN',chapter:3,from:1,to:1,translation:'otb'},at='2026-10-03T12:00:00Z';
function fixture(){const d=empty();d.journal=[{id:'j',text:'Persönliche Notiz',date:at,ref,pathIds:['p'],reflectionId:'r'}];d.reflections=[{id:'r',text:'Persönliche Notiz',date:at,ref,pathIds:['p']}];d.highlights=[{id:'h',...ref,color:'gold',at}];d.paths=[{id:'p',title:'Weg',steps:[],links:[{id:'l',ref,journalId:'j',reflectionId:'r'}],reviews:[{id:'review',text:'Bleibt',sourceKey:'reflection:r',date:at}],milestones:[]}];return d;}
test('Bible note deletion preserves journal, reference, paths, reviews, highlight and color',()=>{const d=fixture(),before=structuredClone(d);const undo=call('deleteBibleNote',d,'journal','j',at);assert.equal(call('bibleNotes',d,ref).length,0);assert.deepEqual(d.paths,before.paths);assert.deepEqual(d.highlights,before.highlights);assert.equal(d.journal[0].text,before.journal[0].text);assert.deepEqual(d.journal[0].ref,ref);assert.deepEqual(d.journal[0].pathIds,['p']);assert.equal(d.reflections[0].id,'r');call('restoreBibleNote',d,undo);assert.deepEqual(d,before);});
test('Unhighlighted and legacy reflection-only notes remain independently deletable',()=>{const d=fixture();d.highlights=[];d.journal=[];assert.equal(call('bibleNotes',d,ref).length,1);call('deleteBibleNote',d,'reflection','r',at);assert.equal(call('bibleNotes',d,ref).length,0);assert.equal(d.reflections[0].text,'Persönliche Notiz');});
test('Only the explicit selected note is deleted; unrelated note stays active',()=>{const d=fixture();d.journal.push({id:'other',text:'Andere Notiz',date:at,ref});call('deleteBibleNote',d,'journal','j',at);assert.deepEqual(call('bibleNotes',d,ref).map(n=>n.id),['other']);});
test('Undo retains unrelated later reading but refuses to overwrite an edited note',()=>{const d=fixture();const undo=call('deleteBibleNote',d,'journal','j',at);d.reading=ref;call('restoreBibleNote',d,undo);assert.deepEqual(d.reading,ref);const next=call('deleteBibleNote',d,'journal','j',at);d.journal[0].text='Neu bearbeitet';assert.throws(()=>call('restoreBibleNote',d,next),/geändert/);assert.equal(d.journal[0].text,'Neu bearbeitet');});
test('Unrelated legacy reflection with same ID or text must not be marked deleted',()=>{const d=fixture();d.reflections[0].ref={...ref,from:2,to:2};call('deleteBibleNote',d,'journal','j',at);assert.equal(d.reflections[0].bibleNoteDeletedAt,undefined);});
test('Deletion and undo roundtrip through existing V5 store and backups without migration',()=>{const map=new Map([[KEYS.main,JSON.stringify(fixture())]]),storage={getItem:k=>map.get(k)??null,setItem:(k,v)=>map.set(k,v),removeItem:k=>map.delete(k)};const store=createStore(storage);const before=store.backup();let undo;store.transact(d=>undo=call('deleteBibleNote',d,'journal','j',at));const exported=store.backup();assert.equal(exported.schemaVersion,5);const next=createStore(storage);assert.equal(call('bibleNotes',next.state,ref).length,0);next.restore(next.prepareImport(exported));assert.equal(call('bibleNotes',next.state,ref).length,0);next.restore(next.prepareImport(before));assert.equal(call('bibleNotes',next.state,ref).length,1);});

import test from 'node:test';import assert from 'node:assert/strict';import {capturePathReviewSource,reviewSourceContext,renderReviewSource} from '../src/path-review-context.js';import {phase3Fixture} from './phase3-fixtures.mjs';import {empty,migrate,createStore,KEYS} from '../src/store.js';
const at='2026-10-16T12:00:00.000Z';
test('path review freezes the exact current step without changing the store or source ID',()=>{
 const data=phase3Fixture(),before=JSON.stringify(data),source=capturePathReviewSource(data,{pathId:'personal-path'},at);assert.equal(source.key,'path:personal-path');assert.equal(source.stepId,'step-0');assert.equal(source.text,'Im nächsten Gespräch ausreden lassen.');assert.equal(JSON.stringify(data),before);
 const review={id:'review',date:at,text:'Mein Rückblick',sourceKey:source.key,sourceSnapshot:source};data.paths[0].steps[0].text='Ein später anders formulierter Schritt.';data.paths[0].steps.unshift({id:'other',text:'Ein ganz anderer Schritt.',done:false});const context=reviewSourceContext(data,review);assert.equal(context.text,source.text);assert.equal(context.state,'snapshot');assert(context.originalRoute.includes('step=step-0'));assert(!context.originalRoute.includes('other'));assert.match(context.note,/anders/);
});
test('legacy path source never invents its old wording from the current first step',()=>{
 const data=phase3Fixture(),r={id:'old',date:at,sourceKey:'path:personal-path',text:'Alter Rückblick'};const x=reviewSourceContext(data,r);assert.equal(x.state,'path-only');assert.equal(x.text,null);assert.match(x.note,/nicht mitgespeichert/);assert(!x.originalRoute?.includes('step='));
});
test('original journal review is exact; edited, missing and ambiguous originals have honest fallbacks',()=>{
 const data=phase3Fixture(),r=data.reviews[0];let x=reviewSourceContext(data,r);assert.equal(x.text,data.journal[0].text);assert.equal(x.originalRoute,'entry/thought-old');data.journal[0].updatedAt='2026-10-01';data.journal[0].text='Nachträglich geändert';x=reviewSourceContext(data,r);assert.equal(x.text,null);assert.equal(x.state,'edited');assert(!renderReviewSource(x,{date:()=>'',link:()=>''}).includes('Nachträglich geändert'));
 data.journal=[];assert.equal(reviewSourceContext(data,r).state,'missing');
});
test('frozen invitation preserves its displayed text when the current step changes',()=>{
 const data=phase3Fixture(),gap={key:'path:personal-path',title:'In Ruhe zuhören',detail:'Du wolltest ausprobieren: „Im nächsten Gespräch ausreden lassen.“',at:'2026-08-01',pathId:'personal-path'};data.paths[0].steps[0].text='Ein anderer Text';const source=capturePathReviewSource(data,{pathId:'personal-path',gap},at);assert.equal(source.text,gap.detail);assert.equal(source.stepId,null);assert.equal(capturePathReviewSource(data,{gap:{key:'journal:thought-old'}},at),null);
});
test('optional path snapshot roundtrips through V5 backup without migration or ID changes',()=>{
 const data=phase3Fixture(),r={id:'review',date:at,text:'Eine selbst bestätigte Entwicklung',sourceKey:'path:personal-path',sourceSnapshot:capturePathReviewSource(data,{pathId:'personal-path'},at),confirmedDevelopment:true};data.paths[0].reviews.push(r);data.paths[0].milestones.push({id:'milestone',date:at,text:r.text,reviewId:r.id});const mem=new Map([[KEYS.main,JSON.stringify(data)]]),storage={getItem:k=>mem.get(k)||null,setItem:(k,v)=>mem.set(k,v),removeItem:k=>mem.delete(k)},store=createStore(storage);assert.deepEqual(store.prepareImport(store.backup()),migrate(data));assert.equal(store.state.version,5);assert.deepEqual(store.state.paths[0].reviews.at(-1).sourceSnapshot,r.sourceSnapshot);
});
test('source snapshot rejects mismatched/future metadata, escapes text and never trusts imported routes',()=>{
 const data=phase3Fixture(),snapshot={...capturePathReviewSource(data,{pathId:'personal-path'},at),text:'<img src=x onerror=alert(1)>',route:'javascript:alert(1)'},r={id:'r',date:at,sourceKey:'path:personal-path',sourceSnapshot:snapshot};let x=reviewSourceContext(data,r);const html=renderReviewSource(x,{date:()=>'',link:(label,route)=>`<a href="#${route}">${label}</a>`});assert.match(html,/&lt;img/);assert.doesNotMatch(html,/javascript:|<img/);r.sourceSnapshot={...snapshot,key:'path:wrong'};assert.equal(reviewSourceContext(data,r).text,null);r.sourceSnapshot={...snapshot,at:'2027-01-01'};assert.equal(reviewSourceContext(data,r).text,null);
});

test('journal edits between a frozen invitation and review save never become the old quoted text',()=>{
 const data=phase3Fixture(),r=data.reviews[0];r.sourceAt=data.journal[0].date;data.journal[0].text='Edited before the review was saved';data.journal[0].updatedAt='2026-08-15T12:00:00.000Z';const x=reviewSourceContext(data,r);assert.equal(x.state,'edited');assert.equal(x.text,null);
});
test('real highlight sources retain a truthful exact-ID reference without invented historical wording',()=>{
